def max_window_sum(xs, k):
    if k <= 1 or k > len(xs):
        return None
    window_sum = sum(xs[:k])
    best = window_sum
    for i in range(k, len(xs)):
        window_sum += xs[i] - xs[i - k]
        if window_sum > best:
            best = window_sum
    return best
```

